f28bbc1a-fe50-407e-9d2e-4cc895571cd1	my-org	image_orchestrator	Image Orchestrator	Fan-out image generation to multiple providers	function	full_cycle	1.0.0	active	{"metadata": {"type": "function", "category": "image", "description": "Fans out image generation across multiple providers", "displayName": "Image Orchestrator"}, "hierarchy": {"team": ["image_openai_generator", "image_google_generator"], "department": "images"}, "input_modes": ["text/plain"], "capabilities": ["image_generation"], "output_modes": ["image/png", "image/jpeg", "application/json"], "configuration": {"function": {"code": "async function handler(input, ctx) {\\n  const { prompt, size = '512x512', n = 1, providers = ['openai','gemini'], deliverableId = null } = input || {};\\n  let last = null;\\n  for (const p of providers) {\\n    last = await ctx.services.images.generate({ prompt, size, n, title: 'Image Orchestrator', provider: p, deliverableId });\\n  }\\n  return last;\\n}", "version": "1", "language": "js", "timeout_ms": 20000}, "execution_profile": "full_cycle", "execution_capabilities": {"can_plan": false, "can_build": true, "requires_human_gate": false}}}	\N	{}	{"hierarchy": {"team": ["image_openai_generator", "image_google_generator"], "department": "images"}, "input_modes": ["text/plain"], "capabilities": ["image_generation"], "output_modes": ["image/png", "image/jpeg", "application/json"], "configuration": {"function": {"code": "async function handler(input, ctx) {\\n  const { prompt, size = '512x512', n = 1, providers = ['openai','gemini'], deliverableId = null } = input || {};\\n  let last = null;\\n  for (const p of providers) {\\n    last = await ctx.services.images.generate({ prompt, size, n, title: 'Image Orchestrator', provider: p, deliverableId });\\n  }\\n  return last;\\n}", "version": "1", "language": "js", "timeout_ms": 20000}, "execution_profile": "full_cycle", "execution_capabilities": {"can_plan": false, "can_build": true, "requires_human_gate": false}}}	2025-10-12 18:39